import{_ as t,o as r,c as e,a8 as s}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"中华基金中学 · 年份未注明 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"cfss","school_zh":"中华基金中学","school_en":"The Chinese Foundation Secondary School","grade":"s1","year":"unknown","year_label":"年份未注明","type":"interview","title":"中华基金中学 · 年份未注明 · 中一 · 面试","anonymous":true,"source_ids":["CF009","CFSS-S1-HIST-GROUP-EXTRA"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/cfss/s1/unknown-interview.md","filePath":"reports/cfss/s1/unknown-interview.md"}'),n={name:"reports/cfss/s1/unknown-interview.md"};function a(l,o,p,i,u,c){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="中华基金中学-·-年份未注明-·-中一-·-面试" tabindex="-1">中华基金中学 · 年份未注明 · 中一 · 面试 <a class="header-anchor" href="#中华基金中学-·-年份未注明-·-中一-·-面试" aria-label="Permalink to &quot;中华基金中学 · 年份未注明 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/cfss">← 返回中华基金中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-cf009" tabindex="-1">资料来源：中华基金中学中一面试往届真题整理.pdf <a class="header-anchor" href="#record-cf009" aria-label="Permalink to &quot;资料来源：中华基金中学中一面试往届真题整理.pdf {#record-cf009}&quot;">​</a></h2><p><strong>资料类型：</strong> 往届题目整理（非逐条实测）</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文及英语</p><p><strong>自我介绍</strong></p><p>以中文及英文介绍姓名、就读小学、兴趣及个人成就。</p></blockquote><blockquote><p><strong>语文：</strong> 中文</p><p><strong>朗读与理解</strong></p><p>朗读文章后回答人物、事件及词语理解问题。</p><p><strong>成语与表达</strong></p><p>解释成语并造句，例子包括“半途而废”“闻鸡起舞”“蹒跚学步”；另有看图说话或即兴演讲，围绕图画内容解释主要意思。问题也可能要求说明如何看待失败，或描述一次从失败中获得教训的经历。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>日常问答</strong></p><p>围绕宠物、爱好及周末活动进行简单问答，例如：</p><ul><li>“Do you have any pets at home? If yes, tell me about them.”</li><li>“What are your hobbies and why do you enjoy them?”</li><li>“What do you usually do on weekends with your family or friends?”</li></ul><p><strong>阅读理解</strong></p><p>阅读短文后回答理解题。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>数理题目示例</strong></p><ul><li>找规律：2, 4, 8, 16, ( )。</li><li>鸡兔同笼：鸡和兔共10只，共28只脚，分别有多少只？</li><li>三个盒子分别装苹果、香蕉和柳丁，每盒有标签，只有一个标签正确；只能打开一个盒子，怎样判断每盒装什么？选择打开哪盒，为什么？</li></ul></blockquote><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>时事与常识</strong></p><ul><li>香港近期的大型活动或政策。</li><li>世界上最大的海洋。</li><li>一年有多少个节气。</li></ul><p><strong>情境处理</strong></p><ul><li>遇到同学欺凌怎么办？</li><li>与同学发生矛盾如何解决？</li></ul><p><strong>小组讨论与合作</strong></p><p>讨论“智能手机对中学生的影响”，并合作设计校园活动方案。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 语言未注明</p><p><strong>个人与家庭</strong></p><ul><li>介绍家庭成员、自己承担的家务及家庭对自己的影响。</li><li>评价自己在第一轮小组面试中的表现，以及从其他同学身上学到了什么。</li></ul><p><strong>发展规划</strong></p><ul><li>对中学生活有何期望，希望参加哪些社团？</li><li>希望在中学继续发展哪方面的兴趣？</li><li>未来理想职业是什么，中学可以怎样协助实现目标？</li></ul><p><strong>学校了解</strong></p><ul><li>为什么选择中华基金中学？</li><li>如何理解“立根中华文化，开拓国际视野，五育并重，发挥个人潜能”的学校愿景？</li><li>对STEM教育或学校增益课程有什么了解？</li></ul></blockquote><h2 id="record-cfss-s1-hist-group-extra" tabindex="-1">资料来源：中华基金中学中一入学信息.pdf <a class="header-anchor" href="#record-cfss-s1-hist-group-extra" aria-label="Permalink to &quot;资料来源：中华基金中学中一入学信息.pdf {#record-cfss-s1-hist-group-extra}&quot;">​</a></h2><p><strong>资料类型：</strong> 机构转述往届家长反馈</p><p><strong>入学途径：</strong> 普通升中</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示-1" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示-1" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文</p><p><strong>平板题目与小组任务</strong></p><p>先阅读平板上的中文题目，在草稿纸记录答案；小组环节兼有语文知识考核，包括重组句子、成语及阅读理解。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>一分钟描述、排序与讨论</strong></p><p>每位考生各有一幅图，用约1分钟英文介绍；全部介绍完后，讨论图画顺序并解释原因。老师会单独追问，例如：想带哪些物品进入故事？为什么？</p></blockquote><h3 id="第二轮-·-原文明示-1" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示-1" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>综合面试：</strong> 中文及英语</p><p><strong>个人对谈｜一组反馈约20分钟</strong></p><p>与资深老师、主任或校长等面谈，涉及个人生活、选校原因、学校吸引之处、交通安排，以及是否申请其他直资学校。英文包括朗读文章、阅读理解及问答，日常例题有“What’s your favorite hobby?”和“What do you usually do on weekends?”。</p></blockquote>',24)])])}const d=t(n,[["render",a]]);export{h as __pageData,d as default};
